with prev_events as (select *, lag(reading_ts) over (partition by device_code order by reading_ts, id) as prev_reading_ts from device_readings), gaps as (select *, case when prev_reading_ts is null or reading_ts > prev_reading_ts + interval 30 minutes then 1 else 0 end as is_new_burst from prev_events), sessions_device_readings as (select id, device_code, reading_ts, humidity, pressure, status_bits, firmware, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from gaps) select id, device_code, humidity, pressure, status_bits, firmware, session_id from sessions_device_readings
